-    if(h) for(const o of portadorObjects){ if(o.kind === 'ex_reflection' && o.owner === h && o.life > 0){ kvbBeam('nh_cut', o.x, o.y, ex, ey, r * 1.1, 480, {layer: 't', alpha: .7}); kvbEmit('nh_glint', 2, o.x, o.y, {v0: 10, v1: 40, l0: 260, l1: 420, scale: 1.2}); } }
